INSERT INTO `crm_chat_messages` (`id`, `lead_id`, `user_id`, `sender_type`, `sender_name`, `message`, `attachment_image`, `sent_via_wa`, `created_at`) VALUES
(1, 111, 9, 'agent', 'Syaifur Rahmatullah', 'Halo Kak *Teuku Makarim El-pribadi*, izin menyapa kembali dari tim PMB *CYBER UNIVERSITY* 😊 Apakah informasi kegiatan dan pendaftaran yang kami kirimkan sebelumnya sudah diterima Kak? Jika ada yang ingin ditanyakan seputar jurusan atau beasiswa, silakan balas pesan ini ya Kak 🙏', NULL, 1, '2026-10-29 13:21:05'),
(2, 114, 9, 'agent', 'Syaifur Rahmatullah', 'Halo Kak *Widi Ulfia Putri* dari *MAN 1 KOTA SUKABUMI*! 👋😊\r\n\r\nPerkenalkan saya dari tim Admisi *CYBER UNIVERSITY*. Terima kasih banyak ya sudah berpartisipasi pada kegiatan *Edufair SMKN 22 Jkt* bersama kami! 🙌\r\n\r\nKami ingin berbagi informasi seputar peluang kuliah, pilihan jurusan favorit, serta jalur Beasiswa PMB di *CYBER UNIVERSITY*.\r\n\r\nNgomong-ngomong, setelah lulus nanti Kak Widi Ulfia Putri paling tertarik di bidang atau jurusan apa nih? Yuk sharing sebentar Kak! 😊', NULL, 0, '2026-10-29 23:16:35');
